// One digest line per ward, plus the comparison the product exists to make.
// `claims_done` is the department's word; `verified_fixed` is a photograph that
// passed a check. Reporting them as one number is the thing we refuse to do.
const rows = items.map(i => i.json).filter(r => r && r.ward);

if (!rows.length) {
  return [{ json: { empty: true, digest: 'No non-seed reports yet — nothing to publish.' } }];
}

const totals = rows.reduce((a, r) => ({
  filed: a.filed + Number(r.filed || 0),
  claims: a.claims + Number(r.claims_done || 0),
  verified: a.verified + Number(r.verified_fixed || 0),
  escalated: a.escalated + Number(r.escalated || 0),
}), { filed: 0, claims: 0, verified: 0, escalated: 0 });

const lines = rows.slice(0, 10).map(r =>
  `Ward ${r.ward} (${r.zone}) — ${r.filed} filed · ${r.claims_done} claimed fixed · ${r.verified_fixed} verified · median ${r.median_days_open}d open`
);

const verifiedPct = totals.filed ? ((totals.verified / totals.filed) * 100).toFixed(1) : '0.0';

const digest = [
  `CivicAgent — weekly ward accountability`,
  ``,
  `${totals.filed} reports filed. ${totals.claims} claimed fixed by the department.`,
  `${totals.verified} verified by a resident's photograph (${verifiedPct}%).`,
  `${totals.escalated} past the authority's own published deadline.`,
  ``,
  ...lines,
].join('\n');

return [{ json: { digest, totals, wards: rows.length } }];
